const input = $input.first().json;
const periodEnd = new Date();
const periodStart = new Date(periodEnd);
periodStart.setUTCDate(periodStart.getUTCDate() - 7);
const clientConfig = { clientId: input.clientId || 'CLI-001', clientName: input.clientName || 'Proyecto Pekín', hubspotCompanyId: '<CONFIGURE_HUBSPOT_COMPANY_ID>', slidesTemplateId: '16SvDTUUF9q7VspDWbX8Zr4YTU6QJi__L3oh5qvJYtq0', driveFolderId: '<CONFIGURE_GOOGLE_DRIVE_FOLDER_ID>', weeklyLeadGoal: 100, weeklyInvestmentGoal: 5000000, timezone: 'America/Bogota' };
return [{ json: { ...input, ...clientConfig, periodStart: periodStart.toISOString(), periodEnd: periodEnd.toISOString() } }];

const input = $input.first().json;
const metrics = {
  recognition: { kpi: 125000, actual: 14014, performance: 11.21, budget: 500000, investment: 48732 },
  investors: { kpi: 120, leads: 62, performance: 51.67, budget: 1200000, investment: 288141, cpa: 5145 },
  housing: { kpi: 40, leads: 17, performance: 42.50, budget: 400000, investment: 97517, cpa: 5736 },
  studio: { investment: 95888, leads: 6, cpa: 15981 },
  pmax: { kpi: 30, leads: 24, performance: 80.00, budget: 1200000, investment: 381000 },
  totals: { targetLeads: 190, generatedLeads: 103, performance: 54.21, remainder: 2388801 },
  leadsRegistered: 103,
  mqls: 41,
  noNicho: 12,
  pendingClassification: 8,
  sales: 5,
  actualInvestment: 4650000
};
const leadAchievement = Number(((metrics.leadsRegistered / input.weeklyLeadGoal) * 100).toFixed(1));
const cpl = Math.round(metrics.actualInvestment / metrics.leadsRegistered);
return [{ json: { ...input, ...metrics, leadAchievement, cpl, dataSource: 'mock' } }];

const input = $input.first().json;
const strategicCopy = { ANALISIS_TENDENCIA_VIVIENDA: `Durante el período observamos ${input.leadsRegistered} registros, equivalentes al ${input.leadAchievement}% de la meta semanal.`, RECOMENDACION_AGENCIA_VIVIENDA: `Desde la agencia, consideramos prioritario mantener la optimización de audiencias y creatividades para sostener un CPL cercano a $${input.cpl.toLocaleString('es-CO')}.`, SINTESIS_EMBUDO: `El embudo registra ${input.mqls} MQL, ${input.pendingClassification} contactos pendientes de clasificación y ${input.sales} ventas.` };
return [{ json: { ...input, strategicCopy, aiSource: 'mock' } }];

const input = $input.first().json;
const divider = '\u2501'.repeat(14);
const finalMessage = [
  '\u2705 *TIC TAC | INFORME COMPLETADO*',
  divider,
  `\u{1F3E2} *Proyecto:* ${input.clientName}`,
  `\u{1F4CA} *Leads generados:* ${input.leadsRegistered}`,
  `\u{1F3AF} *Cumplimiento:* ${input.leadAchievement}%`,
  `\u{1F4B0} *CPL promedio:* $${input.cpl.toLocaleString('es-CO')}`,
  '',
  `\u{1F4C1} *Ver informe:* ${input.reportUrl}`,
  divider,
  '\u2139\uFE0F _Versi\u00f3n de prueba con datos simulados._',
  '_Tic Tac Agency Performance SAS_'
].join('\n');
return [{ json: { ...input, finalMessage } }];
